/* urIQ service worker – generated by tools/pwa/build_sw.py, do not edit by hand.
   Pages: network first, the cached copy when offline. Everything else: cached copy first,
   refreshed in the background. */
var VERSION='urIQ-__VERSION__';
var PRECACHE=__PRECACHE__;

self.addEventListener('install',function(e){
  e.waitUntil(caches.open(VERSION).then(function(c){
    return Promise.all(PRECACHE.map(function(u){
      return fetch(u,{cache:'reload'}).then(function(r){ if(r.ok) return c.put(u,r); }).catch(function(){});
    }));
  }).then(function(){ return self.skipWaiting(); }));
});

self.addEventListener('activate',function(e){
  e.waitUntil(caches.keys().then(function(keys){
    return Promise.all(keys.filter(function(k){ return k.indexOf('urIQ-')===0&&k!==VERSION; }).map(function(k){ return caches.delete(k); }));
  }).then(function(){ return self.clients.claim(); }));
});

self.addEventListener('fetch',function(e){
  var req=e.request, url=new URL(req.url);
  if(req.method!=='GET'||url.origin!==self.location.origin) return;
  var page=req.mode==='navigate'||(req.headers.get('accept')||'').indexOf('text/html')>=0;
  if(page){
    e.respondWith(fetch(req).then(function(r){
      if(r.ok){ var copy=r.clone(); caches.open(VERSION).then(function(c){ c.put(req,copy); }); }
      return r;
    }).catch(function(){
      return caches.match(req).then(function(hit){
        return hit||caches.match(req,{ignoreSearch:true}).then(function(h2){ return h2||caches.match('index.html',{ignoreSearch:true}); });
      });
    }));
    return;
  }
  e.respondWith(caches.match(req).then(function(hit){
    var net=fetch(req).then(function(r){
      if(r.ok){ var copy=r.clone(); caches.open(VERSION).then(function(c){ c.put(req,copy); }); }
      return r;
    }).catch(function(){ return hit||caches.match(req,{ignoreSearch:true}); });
    return hit||net;
  }));
});
